GVL_IO.stInputs.bPbupMagnetPresent 			:= GVL_EtherCAT.stTerm7_EL1809.iEL1809_Ch16;

(*
======================================================================================================================
 INDEX Position
======================================================================================================================
*)
uiIndexPositionCode := 0;

IF GVL_IO.stInputs.bIndexPositionSensor1 THEN 
	uiIndexPositionCode := uiIndexPositionCode + 1; 
END_IF

IF GVL_IO.stInputs.bIndexPositionSensor2 THEN 
	uiIndexPositionCode := uiIndexPositionCode + 2; 
END_IF

IF GVL_IO.stInputs.bIndexPositionSensor3 THEN 
	uiIndexPositionCode := uiIndexPositionCode + 4; 
END_IF

IF GVL_IO.stInputs.bIndexLocked THEN 
	GVL_IO.stInputs.eIndexPosition := UINT_TO_E_TablePosition(uiIndexPositionCode);
ELSE 
	GVL_IO.stInputs.eIndexPosition := E_TablePosition.Unknown; 
END_IF

(*
======================================================================================================================
 Terminal 8 | EL1809
======================================================================================================================
*)

GVL_IO.stInputs.bStation1SupportRetracted 		:= GVL_EtherCAT.stTerm8_EL1809.iEL1809_Ch2; (*Inverted*)
