GVL_MASTER.stStationEvents[1].aEvents[0].bEventText := GVL_MASTER.stStatus.sAutoCycleBlockReason;
GVL_MASTER.stStationEvents[1].aEvents[0].sSolution := 'Commission Patch Dispense, Heat Stake and Vision stations';



// Patch feeding NC/PLCopen diagnostics, one event per motor.
GVL_MASTER.stStationEvents[3].aEvents[31].bFault := TRUE;
GVL_MASTER.stStationEvents[3].aEvents[31].bEventFlag :=
    GVL_Motion.AxisDriveMotor.bError AND NOT GVL_Motion.stPatchFeedStatus.bResetPending;
