    GVL_Motion.AxisPatchFeedRollMotor.bError AND NOT GVL_Motion.stPatchFeedStatus.bResetPending;
GVL_MASTER.stStationEvents[3].aEvents[32].bEventText := CONCAT('M2 Patch Feed Roll: axis error ', UDINT_TO_STRING(GVL_Motion.AxisPatchFeedRollMotor.udiErrorId));
GVL_MASTER.stStationEvents[3].aEvents[32].sSolution := 'Check NC and drive diagnostics; correct cause before operator Reset.';

GVL_MASTER.stStationEvents[3].aEvents[33].bFault := TRUE;
GVL_MASTER.stStationEvents[3].aEvents[33].bEventFlag :=
