GVL_MASTER.stStationEvents[3].aEvents[33].bEventText := CONCAT('M3 Waste Roll: axis error ', UDINT_TO_STRING(GVL_Motion.AxisWasteRollMotor.udiErrorId));
GVL_MASTER.stStationEvents[3].aEvents[33].sSolution := 'Check NC and drive diagnostics; correct cause before operator Reset.';

GVL_MASTER.stStationEvents[3].aEvents[34].bFault := TRUE;
