GVL_MASTER.stStationEvents[3].aEvents[34].sSolution := 'Check rocker sensors and motion timeout; do not repeatedly retry a jammed web.';

// Explicit commissioning indication; no fault is suppressed by this message.
GVL_MASTER.stStationEvents[3].aEvents[35].bMessage := TRUE;
GVL_MASTER.stStationEvents[3].aEvents[35].bPersistentMessage := TRUE;
GVL_MASTER.stStationEvents[3].aEvents[35].bEventFlag :=
    GVL_MASTER.stStatus.stPatchDispense.bCommissioned
    AND NOT GVL_Motion.stPatchFeedSettings.bUsePatchVerticalFeedback;
GVL_MASTER.stStationEvents[3].aEvents[35].bEventText := 'Patch vertical: TEMP timed mode';
GVL_MASTER.stStationEvents[3].aEvents[35].sSolution :=
    'No position feedback. Wire Input9/Input10, validate and restore feedback mode.';

// Missing load components are start-only warnings, never machine faults or cycle stops.
aWarningEvents[1, 2] := TRUE;
GVL_MASTER.stStationEvents[1].aEvents[2].bMessage := TRUE;
