    GVL_MASTER.stStatus.stOperatorStation.bMissingPbupAlert;
GVL_MASTER.stStationEvents[1].aEvents[2].bEventText := 'Operator nest: PBUP missing';
GVL_MASTER.stStationEvents[1].aEvents[2].sSolution :=
