declaration:
FUNCTION_BLOCK FB_OperatorStation
VAR
    eState                    : E_OperatorExchangeState := E_OperatorExchangeState.Idle;
    eInstruction              : E_OperatorInstruction := E_OperatorInstruction.None;
    sMessage                  : STRING(255);
    stStatusInternal          : ST_OperatorStationStatus;

    bExchangeComplete         : BOOL;
    bPartRemovedConfirmed     : BOOL;
    bRejectConfirmed          : BOOL;
    bRejectArmed              : BOOL;
    bRejectEdgeAccepted       : BOOL;
    bPreviousRejectSensor     : BOOL;
    bRejectPulse              : BOOL;
    rtIndexAttempt : R_TRIG;
    bIndexAttemptActive : BOOL;
    bLoadSetComplete : BOOL;
    bLoadSetEmpty : BOOL;
    bMissingPbupAlert : BOOL;
    bMissingProductAlert : BOOL;
END_VAR

METHOD PUBLIC Cyclic
VAR_INPUT
    bAutomaticActive          : BOOL;
    bIndexStable              : BOOL;
    stOperatorNest            : ST_Nest;
    bPartPresent              : BOOL;
    bPbupPresent : BOOL;
    bTwoHandsSafe : BOOL;
    bResetRequest : BOOL;
    bRejectChutePartPresent   : BOOL;
    bRequireRejectConfirm     : BOOL;
    bAllowEmptyNestIndex      : BOOL;
END_VAR

implementation:
// Product and PBUP form one load set; retain the legacy product/reject semantics.
bLoadSetComplete := bPartPresent AND bPbupPresent;
bLoadSetEmpty := NOT bPartPresent AND NOT bPbupPresent;
rtIndexAttempt(CLK := bTwoHandsSafe);
IF NOT bAutomaticActive OR NOT bTwoHandsSafe OR NOT bIndexStable OR bResetRequest THEN
    bIndexAttemptActive := FALSE;
ELSIF rtIndexAttempt.Q THEN
    bIndexAttemptActive := TRUE;
END_IF
IF NOT bAutomaticActive OR bResetRequest OR NOT (bPartPresent XOR bPbupPresent) THEN
    bMissingPbupAlert := FALSE;
    bMissingProductAlert := FALSE;
ELSIF bIndexAttemptActive THEN
    bMissingPbupAlert := bPartPresent AND NOT bPbupPresent;
    bMissingProductAlert := bPbupPresent AND NOT bPartPresent;
END_IF


bRejectPulse :=
    bRejectChutePartPresent
    AND NOT bPreviousRejectSensor;

bPreviousRejectSensor := bRejectChutePartPresent;
bRejectEdgeAccepted := FALSE;

IF NOT bAutomaticActive THEN

    eState := E_OperatorExchangeState.Idle;
    bExchangeComplete := FALSE;
    bPartRemovedConfirmed := FALSE;
    bRejectConfirmed := FALSE;
    bRejectArmed := FALSE;
    eInstruction := E_OperatorInstruction.None;
    sMessage := '';

ELSE

    CASE eState OF

        E_OperatorExchangeState.Idle:
            bExchangeComplete := FALSE;
            eInstruction := E_OperatorInstruction.None;
            sMessage := '';

            IF bIndexStable THEN
                eState := E_OperatorExchangeState.EvaluateNest;
            END_IF

        E_OperatorExchangeState.EvaluateNest:
            bExchangeComplete := FALSE;
            bPartRemovedConfirmed := FALSE;
            bRejectConfirmed := FALSE;
            bRejectArmed := FALSE;

            IF stOperatorNest.stResult.bValid
				OR (stOperatorNest.eDisposition = E_PartDisposition.Reprocess)
			THEN

                IF bPartPresent THEN
                    eState := E_OperatorExchangeState.WaitingForPartRemoval;
                ELSE
                    bPartRemovedConfirmed := TRUE;

					IF (stOperatorNest.eDisposition <> E_PartDisposition.Reprocess)
						AND NOT stOperatorNest.stResult.bPassed
						AND bRequireRejectConfirm
					THEN
                        eState := E_OperatorExchangeState.WaitingForRejectConfirmation;
                    ELSE
                        eState := E_OperatorExchangeState.WaitingForPartLoading;
                    END_IF
                END_IF

            ELSE
                eState := E_OperatorExchangeState.WaitingForPartLoading;
            END_IF

        E_OperatorExchangeState.WaitingForPartRemoval:

            IF stOperatorNest.eDisposition = E_PartDisposition.Reprocess THEN

				// Reprocess is neither PASS nor definitive FAIL.
				// The operator must remove the part, but it must NOT
				// be sent to the reject chute.
				eInstruction :=
					E_OperatorInstruction.RemoveFailedPart;

				sMessage :=
					'Remove part for reprocess';

			ELSIF stOperatorNest.stResult.bPassed THEN

				eInstruction :=
					E_OperatorInstruction.RemovePassedPart;

				sMessage :=
					'Remove passed part from operator nest';

			ELSE

				eInstruction :=
					E_OperatorInstruction.RemoveFailedPart;

				sMessage :=
					'Remove failed part from operator nest';

			END_IF

            IF NOT bPartPresent THEN
                bPartRemovedConfirmed := TRUE;
                bRejectArmed := FALSE;

				IF (stOperatorNest.eDisposition = E_PartDisposition.Reprocess) THEN

					// Reprocess parts must NOT go to the reject chute.
					eState :=
						E_OperatorExchangeState.WaitingForPartLoading;

				ELSIF NOT stOperatorNest.stResult.bPassed
					AND bRequireRejectConfirm
				THEN

					eState :=
						E_OperatorExchangeState.WaitingForRejectConfirmation;

				ELSE

					eState :=
						E_OperatorExchangeState.WaitingForPartLoading;

				END_IF
            END_IF

        E_OperatorExchangeState.WaitingForRejectConfirmation:

            eInstruction := E_OperatorInstruction.PlacePartInRejectBin;

            IF NOT bRejectChutePartPresent THEN
                bRejectArmed := TRUE;
            END_IF

            IF NOT bRejectArmed THEN
                sMessage := 'Clear reject chute, then place the failed part into reject chute';
            ELSE
                sMessage := 'Place failed part into reject chute';
            END_IF

            IF bPartRemovedConfirmed
                AND bRejectArmed
                AND bRejectPulse
            THEN
                bRejectConfirmed := TRUE;
                bRejectEdgeAccepted := TRUE;
            END_IF

            IF bPartRemovedConfirmed
                AND bRejectConfirmed
            THEN
                eState := E_OperatorExchangeState.WaitingForPartLoading;
            END_IF

        E_OperatorExchangeState.WaitingForPartLoading:
            bExchangeComplete := FALSE;
            eInstruction := E_OperatorInstruction.LoadPart;
            IF bLoadSetComplete THEN
                eInstruction := E_OperatorInstruction.ReadyToIndex;
                sMessage := 'Product and PBUP loaded - press two-hand buttons to index';
                bExchangeComplete := TRUE;
                eState := E_OperatorExchangeState.ExchangeComplete;
            ELSIF bLoadSetEmpty AND bAllowEmptyNestIndex THEN
                eInstruction := E_OperatorInstruction.ReadyToIndexEmpty;
                sMessage := 'Load product and PBUP or continue with empty nest';
                bExchangeComplete := TRUE;
                eState := E_OperatorExchangeState.ExchangeComplete;
            ELSIF bPartPresent THEN
                sMessage := 'PBUP missing - load PBUP or remove product';
            ELSIF bPbupPresent THEN
                sMessage := 'Product missing - load product or remove PBUP';
            ELSE
                sMessage := 'Load product and PBUP into operator nest';
            END_IF

        E_OperatorExchangeState.ExchangeComplete:
            // Never use a latched exchange completion to permit a later partial load.
            IF NOT bIndexStable THEN
                eState := E_OperatorExchangeState.WaitingForTableIndexComplete;
            ELSIF bLoadSetComplete THEN
                bExchangeComplete := TRUE;
                eInstruction := E_OperatorInstruction.ReadyToIndex;
                sMessage := 'Product and PBUP loaded - press two-hand buttons to index';
            ELSIF bLoadSetEmpty AND bAllowEmptyNestIndex THEN
                bExchangeComplete := TRUE;
                eInstruction := E_OperatorInstruction.ReadyToIndexEmpty;
                sMessage := 'Empty nest - press two-hand buttons to index';
            ELSE
                bExchangeComplete := FALSE;
                eState := E_OperatorExchangeState.WaitingForPartLoading;
                eInstruction := E_OperatorInstruction.LoadPart;
                IF bPartPresent THEN
                    sMessage := 'PBUP missing - load PBUP or remove product';
                ELSIF bPbupPresent THEN
                    sMessage := 'Product missing - load product or remove PBUP';
                ELSE
                    sMessage := 'Load product and PBUP into operator nest';
                END_IF
            END_IF

        E_OperatorExchangeState.WaitingForTableIndexComplete:

            eInstruction := E_OperatorInstruction.TableIndexing;
            sMessage := 'Table index in progress';

            IF bIndexStable THEN
                bExchangeComplete := FALSE;
                bPartRemovedConfirmed := FALSE;
                bRejectConfirmed := FALSE;
                bRejectArmed := FALSE;
                eState := E_OperatorExchangeState.EvaluateNest;
            END_IF

        E_OperatorExchangeState.Fault:
            bExchangeComplete := FALSE;
            eInstruction := E_OperatorInstruction.None;
            sMessage := 'Operator exchange fault';

    END_CASE
END_IF

stStatusInternal.eState := eState;
stStatusInternal.eInstruction := eInstruction;

stStatusInternal.bExchangeComplete := bExchangeComplete;

stStatusInternal.bIndexPermissive :=
    bExchangeComplete
    AND eState = E_OperatorExchangeState.ExchangeComplete
    AND (bLoadSetComplete OR (bLoadSetEmpty AND bAllowEmptyNestIndex));

stStatusInternal.bPartRemovedConfirmed := bPartRemovedConfirmed;
stStatusInternal.bRejectConfirmed := bRejectConfirmed;
stStatusInternal.bRejectArmed := bRejectArmed;
stStatusInternal.bRejectEdgeAccepted := bRejectEdgeAccepted;

stStatusInternal.bRejectWaitingForClear :=
    (eState = E_OperatorExchangeState.WaitingForRejectConfirmation)
    AND NOT bRejectArmed;

stStatusInternal.bRejectPopupRequest :=
    (
        eState = E_OperatorExchangeState.WaitingForPartRemoval
        AND (stOperatorNest.eDisposition <> E_PartDisposition.Reprocess)
        AND stOperatorNest.stResult.bValid
        AND NOT stOperatorNest.stResult.bPassed
    )
    OR
    (
        eState = E_OperatorExchangeState.WaitingForRejectConfirmation
        AND (stOperatorNest.eDisposition <> E_PartDisposition.Reprocess)
    );

stStatusInternal.bPartPresent := bPartPresent;
stStatusInternal.bRejectChutePartPresent := bRejectChutePartPresent;
stStatusInternal.bResultValid := stOperatorNest.stResult.bValid;
stStatusInternal.bResultPassed := stOperatorNest.stResult.bPassed;
stStatusInternal.sMessage := sMessage;







stStatusInternal.bPbupPresent := bPbupPresent;
stStatusInternal.bLoadSetComplete := bLoadSetComplete;
stStatusInternal.bMissingPbup := bPartPresent AND NOT bPbupPresent;
stStatusInternal.bMissingProduct := bPbupPresent AND NOT bPartPresent;
stStatusInternal.bMissingPbupAlert := bMissingPbupAlert;
stStatusInternal.bMissingProductAlert := bMissingProductAlert;

declaration:
METHOD PUBLIC Cyclic
VAR_INPUT
    bIndexStable : BOOL;
    eIndexPosition : E_TablePosition;
    eOperatorPosition : E_TablePosition;
    bPartPresent : BOOL;
    bPbupPresent : BOOL;
    bOperatorReloadPermitted : BOOL;
    aNestEnabled : ARRAY[1..4] OF BOOL;
END_VAR
VAR
    bOperatorRecordProtected : BOOL;
END_VAR

implementation:
IF NOT bInitialised THEN
    FOR i := 1 TO 4 DO
        aNestInternal[i].nId := INT_TO_UINT(i);
        aNestStatisticsInternal[i].uiNestId := INT_TO_UINT(i);
    END_FOR
    bInitialised := TRUE;
END_IF
FOR i := 1 TO 4 DO
    aNestInternal[i].bEnabled := aNestEnabled[i];
    // Pulse semantics do not depend on whether the index is moving.
    aNestInternal[i].bPartLoadedPulse := FALSE;
    aNestInternal[i].bPartRemovedPulse := FALSE;
END_FOR
IF bIndexStable AND (eIndexPosition <> E_TablePosition.Unknown) THEN
    CASE eIndexPosition OF
        E_TablePosition.Position1:
            aPositionToNest[1] := 1;
            aPositionToNest[2] := 4;
            aPositionToNest[3] := 3;
            aPositionToNest[4] := 2;
        E_TablePosition.Position2:
            aPositionToNest[1] := 2;
            aPositionToNest[2] := 1;
            aPositionToNest[3] := 4;
            aPositionToNest[4] := 3;
        E_TablePosition.Position3:
            aPositionToNest[1] := 3;
            aPositionToNest[2] := 2;
            aPositionToNest[3] := 1;
            aPositionToNest[4] := 4;
        E_TablePosition.Position4:
            aPositionToNest[1] := 4;
            aPositionToNest[2] := 3;
            aPositionToNest[3] := 2;
            aPositionToNest[4] := 1;
    END_CASE
    FOR i := 1 TO 4 DO
        aNestInternal[aPositionToNest[i]].ePosition := UINT_TO_E_TablePosition(INT_TO_UINT(i));
        aNestInternal[i].bPartLoadedPulse := FALSE;
        aNestInternal[i].bPartRemovedPulse := FALSE;
    END_FOR
    uiNest := aPositionToNest[TO_UINT(eOperatorPosition)];
    // Preserve a completed/reprocess product while its operator/reject exchange is pending.
    bOperatorRecordProtected := aNestInternal[uiNest].stResult.bValid
        OR (aNestInternal[uiNest].eDisposition = E_PartDisposition.Reprocess);
    aNestInternal[uiNest].bPartLoadedPulse := bPartPresent
        AND ((NOT bOperatorRecordProtected AND NOT aNestInternal[uiNest].bPreviousPartPresent)
            OR (bOperatorRecordProtected AND bOperatorReloadPermitted));

    aNestInternal[uiNest].bPartRemovedPulse :=
        NOT bPartPresent AND aNestInternal[uiNest].bPreviousPartPresent;

    IF aNestInternal[uiNest].bPartLoadedPulse THEN
        aNestInternal[uiNest].bProcessRequired := TRUE;
        aNestInternal[uiNest].bProcessComplete := FALSE;
        aNestInternal[uiNest].eDisposition := E_PartDisposition.None;
        aNestInternal[uiNest].bDispositionSent := FALSE;
        aNestInternal[uiNest].bOperatorExchangeComplete := FALSE;

        aNestInternal[uiNest].stPatchDispenseResult.bValid := FALSE;
        aNestInternal[uiNest].stPatchDispenseResult.bPassed := FALSE;
        aNestInternal[uiNest].stPatchDispenseResult.eCode := E_ProcessResultCode.None;
        aNestInternal[uiNest].stHeatStakeResult.bValid := FALSE;
        aNestInternal[uiNest].stHeatStakeResult.bPassed := FALSE;
        aNestInternal[uiNest].stHeatStakeResult.eCode := E_ProcessResultCode.None;
        aNestInternal[uiNest].stVisionResult.bValid := FALSE;
        aNestInternal[uiNest].stVisionResult.bPassed := FALSE;
        aNestInternal[uiNest].stVisionResult.eCode := E_ProcessResultCode.None;

        aNestInternal[uiNest].ePatchDispenseStage := E_NestStageStatus.Waiting;
        aNestInternal[uiNest].eHeatStakeStage := E_NestStageStatus.Waiting;
        aNestInternal[uiNest].eVisionStage := E_NestStageStatus.Waiting;

        aNestInternal[uiNest].stResult.bValid := FALSE;
        aNestInternal[uiNest].stResult.bPassed := FALSE;
        aNestInternal[uiNest].stResult.eCode := E_ProcessResultCode.None;
        aNestInternal[uiNest].bStatisticsCounted := FALSE;
    END_IF

    // Raw PBUP pocket presence is current at Operator, frozen while the nest travels.
    aNestInternal[uiNest].bPbupPresent := bPbupPresent;
    // A PBUP assembled at Vision may no longer occupy its original pocket.
    // Do not overwrite the paired-load history of a returned processed product.
    IF NOT bOperatorRecordProtected OR aNestInternal[uiNest].bPartLoadedPulse THEN
        aNestInternal[uiNest].bLoadSetComplete := bPartPresent AND bPbupPresent;
    END_IF
    aNestInternal[uiNest].bPreviousPartPresent := bPartPresent;
    aNestInternal[uiNest].bPartPresent := bPartPresent;
END_IF

uiMethodNestId := GetNestIdAtPosition(ePosition);

IF uiMethodNestId >= 1 AND uiMethodNestId <= 4 THEN
    aNestInternal[uiMethodNestId].bPbupPresent := FALSE;
    aNestInternal[uiMethodNestId].bLoadSetComplete := FALSE;
    aNestInternal[uiMethodNestId].bProcessRequired := FALSE;
    aNestInternal[uiMethodNestId].bProcessComplete := FALSE;
    aNestInternal[uiMethodNestId].eDisposition := E_PartDisposition.None;
    aNestInternal[uiMethodNestId].bDispositionSent := FALSE;
    aNestInternal[uiMethodNestId].bOperatorExchangeComplete := FALSE;

    aNestInternal[uiMethodNestId].stPatchDispenseResult.bValid := FALSE;
    aNestInternal[uiMethodNestId].stPatchDispenseResult.bPassed := FALSE;
    aNestInternal[uiMethodNestId].stPatchDispenseResult.eCode := E_ProcessResultCode.None;
    aNestInternal[uiMethodNestId].stHeatStakeResult.bValid := FALSE;
    aNestInternal[uiMethodNestId].stHeatStakeResult.bPassed := FALSE;
    aNestInternal[uiMethodNestId].stHeatStakeResult.eCode := E_ProcessResultCode.None;
    aNestInternal[uiMethodNestId].stVisionResult.bValid := FALSE;
    aNestInternal[uiMethodNestId].stVisionResult.bPassed := FALSE;
    aNestInternal[uiMethodNestId].stVisionResult.eCode := E_ProcessResultCode.None;

    aNestInternal[uiMethodNestId].ePatchDispenseStage := E_NestStageStatus.Waiting;
    aNestInternal[uiMethodNestId].eHeatStakeStage := E_NestStageStatus.Waiting;
    aNestInternal[uiMethodNestId].eVisionStage := E_NestStageStatus.Waiting;

    aNestInternal[uiMethodNestId].stResult.bValid := FALSE;
    aNestInternal[uiMethodNestId].stResult.bPassed := FALSE;
    aNestInternal[uiMethodNestId].stResult.eCode := E_ProcessResultCode.None;
    aNestInternal[uiMethodNestId].bStatisticsCounted := FALSE;
END_IF

declaration:
METHOD PUBLIC Cyclic
VAR_INPUT
    bEnable                   : BOOL;
    bResetRequest             : BOOL;
    bStopRequest              : BOOL;
    bTwoHandsSafe             : BOOL;
    bSafetyOk                 : BOOL;

    bIndexReady               : BOOL;
    bIndexLocked              : BOOL;
    bIndexBusy                : BOOL;
    bIndexFaulted             : BOOL;
    bStationsIndexPermissive  : BOOL;
    bOperatorIndexPermissive  : BOOL;
    bTemperatureIndexPermissive : BOOL;
    bNestEnableIndexPermissive : BOOL;

    bAllStationsReady         : BOOL;
    bAllStationsComplete      : BOOL;
    bAnyStationFault          : BOOL;
	bHeaterDwellPending 	  : BOOL;

    tSequenceTimeout          : TIME;
END_VAR
VAR_OUTPUT
    bStartStations            : BOOL;
    bStopStations             : BOOL;
    bRequestIndex             : BOOL;

    bCycleActive              : BOOL;
    bCompletePulse            : BOOL;
    bFault                    : BOOL;
    bSequenceTimeoutFault     : BOOL;
    bStopPendingStatus        : BOOL;
    bAutomaticStopRequest     : BOOL;
    bDisabledNestIndexAttempt : BOOL;

    eState                    : E_CycleState;
END_VAR

implementation:
// Generic indexed-machine process coordinator.
//
// Commissioning sequence aligned with the validated Silicone Station pattern:
//
//   AutoCycle enabled
//      -> initialise
//      -> wait until stations are Ready and supports are physically down
//      -> wait for a FRESH validated two-hand actuation
//      -> validate index permissives
//      -> request ONE index movement
//      -> wait for index complete
//      -> start Patch Dispense / Heat Stake / Vision in parallel
//      -> each station extends its own support
//      -> 3 s simulated process
//      -> each station retracts its support
//      -> all stations Complete
//      -> CycleComplete
//      -> wait for next two-hand actuation
//
// The index FB itself remains the final authority for movement:
// it requires Safety Motion Permitted, Two-Hand Safe, and all station
// supports physically retracted before energising the index outputs.

bStartStations := FALSE;
bStopStations := FALSE;
bRequestIndex := FALSE;
bCompletePulse := FALSE;
bAutomaticStopRequest := FALSE;
bDisabledNestIndexAttempt := FALSE;

rtCycleTrigger(CLK := bTwoHandsSafe);

// ---------------------------------------------------------
// ENABLE / RESET / STOP HANDLING
// ---------------------------------------------------------

IF bResetRequest THEN
    bStopPending := FALSE;
    bStartIssued := FALSE;
    bIndexRequestIssued := FALSE;
    bSequenceTimeoutFaultInternal := FALSE;

    IF bEnable THEN
        eStateInternal := E_CycleState.Initialising;
    ELSE
        eStateInternal := E_CycleState.Disabled;
    END_IF

ELSIF NOT bEnable THEN
    bStopPending := FALSE;
    bStartIssued := FALSE;
    bIndexRequestIssued := FALSE;
    bSequenceTimeoutFaultInternal := FALSE;
    eStateInternal := E_CycleState.Disabled;

ELSE
    // Enter the ProcessCycle automatically when the machine enters AutoCycle.
    IF eStateInternal = E_CycleState.Disabled THEN
        bStopPending := FALSE;
        bStartIssued := FALSE;
        bIndexRequestIssued := FALSE;
        eStateInternal := E_CycleState.Initialising;
    END_IF

    IF bStopRequest THEN
        bStopPending := TRUE;
    END_IF
END_IF

// ---------------------------------------------------------
// FAULT SUPERVISION
// ---------------------------------------------------------

IF bIndexFaulted
    OR bAnyStationFault
    OR (bEnable AND NOT bSafetyOk)
THEN
    eStateInternal := E_CycleState.Fault;
END_IF

// Automatic process-cycle timeout.
//
// This timeout represents OPERATOR INACTIVITY only. It must not run while the
// machine is heating, initialising, indexing, processing, stopping or faulted.
//
// It starts only when the machine is fully ready for the next cycle:
//   - AutoCycle/process coordinator enabled;
//   - waiting for a fresh two-hand operator trigger;
//   - Heat Stake temperature permissive is TRUE;
//   - all process stations are Ready;
//   - index is ready/locked and stationary;
//   - station/index permissives are valid.
//
// Therefore the Heat Stake warm-up time is never included in this timeout.
tonSequenceTimeout(
    IN := bEnable
        AND (eStateInternal = E_CycleState.WaitingForProcessCycleTrigger)
        AND bTemperatureIndexPermissive
        AND bAllStationsReady
        AND bSafetyOk
        AND bIndexReady
        AND bIndexLocked
        AND NOT bIndexBusy
        AND bStationsIndexPermissive
        AND bOperatorIndexPermissive,
    PT := tSequenceTimeout
);

IF tonSequenceTimeout.Q THEN
    // Two minutes of a fully-ready machine waiting for operator activity is
    // NOT a machine fault. Convert it into the same controlled Stop Request
    // philosophy used by the physical Stop button.
    bStopPending := TRUE;
    bAutomaticStopRequest := TRUE;
END_IF

// ---------------------------------------------------------
// PROCESS CYCLE
// ---------------------------------------------------------

CASE eStateInternal OF

    E_CycleState.Disabled:
        // Waiting for machine AutoCycle.

    E_CycleState.Initialising:
        bStartIssued := FALSE;
        bIndexRequestIssued := FALSE;

        // Match the Silicone philosophy:
        // do not arm the operator trigger until the index is stable AND all
        // process tooling is physically in the safe/retracted position.
        IF bSafetyOk
            AND bIndexReady
            AND bIndexLocked
            AND bStationsIndexPermissive
            AND bOperatorIndexPermissive
            AND bTemperatureIndexPermissive
            AND bAllStationsReady
        THEN
            eStateInternal := E_CycleState.WaitingForProcessCycleTrigger;
        END_IF

	E_CycleState.WaitingForProcessCycleTrigger:

		IF bStopPending THEN
			eStateInternal := E_CycleState.ControlledStop;

		ELSIF bHeaterDwellPending THEN
			// Block new cycles while waiting for Heater Dwell.
			// The machine controller will perform the safe
			// transition to Dwell.

        // The disabled-nest interlock is reported only after a fresh operator
        // index attempt. The machine stays in this state and does not index.
        ELSIF rtCycleTrigger.Q AND NOT bNestEnableIndexPermissive THEN
            bDisabledNestIndexAttempt := TRUE;

        // Fresh two-hand actuation starts the cycle, exactly as on Silicone.
        ELSIF rtCycleTrigger.Q
            AND bSafetyOk
            AND bIndexReady
            AND bIndexLocked
            AND NOT bIndexBusy
            AND bStationsIndexPermissive
            AND bOperatorIndexPermissive
            AND bAllStationsReady
            AND bNestEnableIndexPermissive
        THEN
            eStateInternal := E_CycleState.ValidatingIndexPermissives;
        END_IF

    E_CycleState.ValidatingIndexPermissives:

        IF bStopPending THEN
            eStateInternal := E_CycleState.ControlledStop;

		ELSIF bHeaterDwellPending THEN
			// No index movement has been requested yet.
			eStateInternal := E_CycleState.WaitingForProcessCycleTrigger;

        ELSIF NOT bOperatorIndexPermissive THEN
            // A load change cancels this attempt; correction alone cannot reuse held hands.
            eStateInternal := E_CycleState.WaitingForProcessCycleTrigger;

        ELSIF bSafetyOk
            AND bStationsIndexPermissive
            AND bOperatorIndexPermissive
            AND bTemperatureIndexPermissive
            AND bNestEnableIndexPermissive
            AND bIndexReady
            AND bIndexLocked
            AND NOT bIndexBusy
        THEN
            eStateInternal := E_CycleState.RequestingIndexMove;
        END_IF

    E_CycleState.RequestingIndexMove:
        IF bStopPending THEN
            eStateInternal := E_CycleState.ControlledStop;
        ELSIF bSafetyOk AND bStationsIndexPermissive AND bOperatorIndexPermissive
            AND bTemperatureIndexPermissive AND bNestEnableIndexPermissive
            AND bIndexReady AND bIndexLocked AND NOT bIndexBusy AND bTwoHandsSafe
            AND NOT bHeaterDwellPending THEN
            bRequestIndex := TRUE;
            bIndexRequestIssued := TRUE;
            eStateInternal := E_CycleState.WaitingForIndexStart;
        ELSE
            // No request is queued with an invalid load or stale two-hand actuation.
            bIndexRequestIssued := FALSE;
            eStateInternal := E_CycleState.WaitingForProcessCycleTrigger;
        END_IF

    E_CycleState.WaitingForIndexStart:

        IF bStopPending THEN
            eStateInternal := E_CycleState.ControlledStop;

        ELSIF bIndexBusy THEN
            eStateInternal := E_CycleState.WaitingForIndexComplete;
        END_IF

    E_CycleState.WaitingForIndexComplete:

        IF bStopPending THEN
            eStateInternal := E_CycleState.ControlledStop;

        ELSIF NOT bIndexBusy
            AND bIndexReady
            AND bIndexLocked
        THEN
            bIndexRequestIssued := FALSE;
            eStateInternal := E_CycleState.PreparingProcessStations;
        END_IF

    E_CycleState.PreparingProcessStations:

        // After the index has locked in its new position, ensure all three
        // station objects are ready before issuing process start.
        IF bStopPending THEN
            eStateInternal := E_CycleState.ControlledStop;

        ELSIF bAllStationsReady THEN
            eStateInternal := E_CycleState.StartingProcesses;
        END_IF

    E_CycleState.StartingProcesses:
        // If Stop was requested before any station actually started, do not
        // launch a new process. Go directly to the controlled-stop path.
        IF bStopPending THEN
            eStateInternal := E_CycleState.ControlledStop;
        ELSE
            bStartStations := TRUE;
            bStartIssued := TRUE;
            eStateInternal := E_CycleState.WaitingForProcessesRunning;
        END_IF

    E_CycleState.WaitingForProcessesRunning:

        // A Stop Request is intentionally only LATCHED while a station is
        // running. Never interrupt an active station process. The process is
        // allowed to reach its normal Complete state and retract its tooling.
        //
        // IMPORTANT:
        // If no physical nest at any process station contains a part, all
        // stations are intentionally skipped. In that case
        // bAllStationsReady remains TRUE forever, while
        // bAllStationsComplete is already TRUE.
        IF bAllStationsComplete THEN
            eStateInternal := E_CycleState.WaitingForProcessesComplete;

        // Normal case: at least one required station has left Ready and
        // entered its process sequence.
        ELSIF NOT bAllStationsReady THEN
            eStateInternal := E_CycleState.WaitingForProcessesComplete;
        END_IF

    E_CycleState.WaitingForProcessesComplete:

        // Even with Stop pending, allow every active station to finish its
        // normal sequence. Only after all stations are Complete and all
        // supports are physically retracted may the stop proceed.
        IF bAllStationsComplete
            AND bStationsIndexPermissive
        THEN
            bStartIssued := FALSE;
            eStateInternal := E_CycleState.CycleComplete;
        END_IF

    E_CycleState.CycleComplete:
        bCompletePulse := TRUE;

        IF bStopPending THEN
            eStateInternal := E_CycleState.ControlledStop;
        ELSE
            eStateInternal := E_CycleState.WaitingForProcessCycleTrigger;
        END_IF

    E_CycleState.ControlledStop:
        bStopStations := TRUE;

        // Safe stop is complete only when the index has stopped and every
        // support cylinder is physically retracted.
        IF NOT bIndexBusy
            AND bStationsIndexPermissive
        THEN
            bStopPending := FALSE;
            eStateInternal := E_CycleState.Disabled;
        END_IF

    E_CycleState.Fault:
        bStopStations := TRUE;

ELSE
    eStateInternal := E_CycleState.Fault;

END_CASE

bCycleActive :=
    (eStateInternal <> E_CycleState.Disabled)
    AND (eStateInternal <> E_CycleState.Fault);

bFault := (eStateInternal = E_CycleState.Fault);
bSequenceTimeoutFault := bSequenceTimeoutFaultInternal;
bStopPendingStatus := bStopPending;
eState := eStateInternal;

